window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[38]={"id":"038","numero":38,"titre":"Infertilité du couple","objectifs":[{"id":"38-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la fertilité, fécondité, fécondabilité d’un couple","contenu":"<p>Trois notions démographiques distinctes, à <strong>ne pas confondre</strong> dans les énoncés EDN. La fiche source décrit le <strong>déclin avec l’âge</strong> mais ne formalise pas les définitions strictes — voir callout ci-dessous.</p>\n\n      <h4>Définitions usuelles</h4>\n\n      <table >\n        <thead>\n          <tr><th>Terme</th><th>Définition</th><th>Ordre de grandeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Fertilité</span></td>\n            <td>Capacité <strong>potentielle</strong> d’un couple à concevoir (aptitude à obtenir une <span class=\"kw-ci\">grossesse</span>).</td>\n            <td><span class=\"kw-chiffre\">60 %</span> à <span class=\"kw-chiffre\">6 mois</span> à<span class=\"kw-chiffre\"> 25 ans</span> · <span class=\"kw-chiffre\">30 %</span> à <span class=\"kw-chiffre\">6 mois</span> à<span class=\"kw-chiffre\"> 35 ans</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Fécondité</span></td>\n            <td>Résultat <strong>effectif</strong> = fait d’avoir conçu (naissance vivante).</td>\n            <td>Indicateur démographique (taux de natalité)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Fécondabilité</span></td>\n            <td>Probabilité de concevoir au cours d’un <strong>cycle menstruel</strong>.</td>\n            <td>≈ <span class=\"kw-chiffre\">25 %</span> par cycle chez le couple normal (à confirmer via Collège)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Chiffres tirés de la fiche source (fertilité selon l’âge)</h4>\n\n      <ul>\n        <li>Fertilité maximale <span class=\"kw-chiffre\">avant 25-28 ans</span> — <span class=\"kw-chiffre\">60 %</span> de <span class=\"kw-ci\">grossesse</span> à <span class=\"kw-chiffre\">6 mois</span> à<span class=\"kw-chiffre\"> 25 ans</span></li>\n        <li><span class=\"kw-clinique\">Diminution dès 31 ans</span>, chute après <span class=\"kw-chiffre\">35 ans</span> — <span class=\"kw-chiffre\">30 %</span> à <span class=\"kw-chiffre\">6 mois</span> à<span class=\"kw-chiffre\"> 35 ans</span></li>\n        <li>Fertilité <strong>presque nulle après <span class=\"kw-chiffre\">45 ans</span></strong></li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> La fiche source <code>fiches sources/38/38-infertilite-couple.md</code> ne formalise pas les définitions strictes de fertilité/fécondité/fécondabilité — Kevin enrichira via Notion ou Collège Gynéco-Obstétrique (chapitre liminaire de la section infertilité).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 39 — Assistance médicale à la procréation</em></p>","frequence":0},{"id":"38-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un couple infertile","contenu":"<p>Définition <strong>opérationnelle</strong> en pratique clinique : déclencheur du bilan d’infertilité du couple (consultation dédiée + examens <span class=\"kw-chiffre\">1ère intention</span>).</p>\n\n      <h4>Définition de l’OMS (référence)</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Couple infertile</strong> = <span class=\"kw-def\">absence de grossesse après ≥ 12 mois de rapports sexuels réguliers non protégés</span>, chez un couple en âge de procréer (OMS). Justifie l’initiation d’un bilan d’infertilité.\n      </div>\n\n      <h4>Nuances pratiques (fiche source)</h4>\n\n      <ul>\n        <li>Optimisation des chances : fréquence des rapports <strong><span class=\"kw-chiffre\">1 jour</span> sur 2</strong>, pendant la fenêtre de fertilité (<span class=\"kw-chiffre\">5 jours précédant l’ovulation</span>)</li>\n        <li>Dysfonction sexuelle dans le couple = <span class=\"kw-chiffre\">3 %</span> des causes d’infertilité (<span class=\"kw-clinique\">vaginisme</span>, <span class=\"kw-clinique\">dyspareunies</span>, <span class=\"kw-clinique\">dysfonction érectile</span>…)</li>\n        <li>Initiation <strong>plus précoce</strong> du bilan si âge maternel <span class=\"kw-chiffre\">≥ 35 ans</span> ou ATCD faisant suspecter une cause (<span class=\"kw-clinique\">chirurgie pelvienne</span>, <span class=\"kw-etio\">IST</span>, <span class=\"kw-clinique\">aménorrhée</span>…)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> La fiche source ne cite pas explicitement le seuil OMS de <span class=\"kw-chiffre\">12 mois</span> — la définition ci-dessus est la référence universelle (Collège Gynéco-Obstétrique, OMS 2009). Kevin enrichira via Notion si une formulation alternative apparaît dans son cours.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 39 — Assistance médicale à la procréation · 23 — <span class=\"kw-ci\">Grossesse</span> normale</em></p>","frequence":0},{"id":"38-3","rang":"B","rubrique":"Epidémiologie, prévalence","titre":"Connaître la fertilité et fécondité dans la population générale","contenu":"<p>La fertilité spontanée du couple est <strong>fortement dépendante de l’âge maternel</strong>. La réserve ovarienne en follicules ovariens diminue <span class=\"kw-clinique\">de façon physiologique avec l’âge en qualité et quantité</span> — phénomène irréversible.</p>\n\n      <h4>Courbe de fertilité féminine selon l’âge</h4>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 190\" role=\"img\" aria-label=\"Courbe du déclin de la fertilité féminine selon l'âge : probabilité de grossesse à 6 mois d'environ 60 % avant 25 à 28 ans (pic), début du déclin dès 31 ans, 30 % à 35 ans qui est le seuil opérationnel, et fertilité presque nulle après 45 ans.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"14\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Déclin de la fertilité féminine avec l'âge</text>\n          <line class=\"ln\" x1=\"60\" y1=\"30\" x2=\"60\" y2=\"160\" stroke-width=\"1.5\"/>\n          <line class=\"ln\" x1=\"60\" y1=\"160\" x2=\"515\" y2=\"160\" stroke-width=\"1.5\"/>\n          <text class=\"tx-muted\" x=\"52\" y=\"43\" text-anchor=\"end\" font-size=\"8\"><span class=\"kw-chiffre\">60 %</span></text>\n          <text class=\"tx-muted\" x=\"52\" y=\"103\" text-anchor=\"end\" font-size=\"8\"><span class=\"kw-chiffre\">30 %</span></text>\n          <text class=\"tx-muted\" x=\"52\" y=\"163\" text-anchor=\"end\" font-size=\"8\"><span class=\"kw-chiffre\">0 %</span></text>\n          <polyline class=\"ln\" fill=\"none\" stroke-width=\"2.5\" points=\"90,40 230,52 340,100 480,158\"/>\n          <circle class=\"fb-ok\" cx=\"90\" cy=\"40\" r=\"4\"/>\n          <circle class=\"fb-amber\" cx=\"230\" cy=\"52\" r=\"4\"/>\n          <circle class=\"fb-red\" cx=\"340\" cy=\"100\" r=\"4.5\"/>\n          <circle class=\"fb-grey\" cx=\"480\" cy=\"158\" r=\"4\"/>\n          <text class=\"tx-ok\" x=\"98\" y=\"34\" font-size=\"8\" font-weight=\"600\">pic (<span class=\"kw-chiffre\">60 %</span>)</text>\n          <text class=\"tx-amber\" x=\"222\" y=\"44\" text-anchor=\"middle\" font-size=\"8\">début du déclin</text>\n          <text class=\"tx-red\" x=\"348\" y=\"96\" font-size=\"8.5\" font-weight=\"700\"><span class=\"kw-chiffre\">30 %</span> — seuil <span class=\"kw-chiffre\">35 ans</span></text>\n          <text class=\"tx-grey\" x=\"478\" y=\"150\" text-anchor=\"end\" font-size=\"8\">≈ nulle</text>\n          <text class=\"tx-muted\" x=\"90\" y=\"174\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\"><span class=\"kw-chiffre\">25 ans</span></text>\n          <text class=\"tx-muted\" x=\"230\" y=\"174\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\"><span class=\"kw-chiffre\">31 ans</span></text>\n          <text class=\"tx-muted\" x=\"340\" y=\"174\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\"><span class=\"kw-chiffre\">35 ans</span></text>\n          <text class=\"tx-muted\" x=\"480\" y=\"174\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\">&gt;<span class=\"kw-chiffre\"> 45 ans</span></text>\n        </svg>\n        <figcaption>Probabilité de <span class=\"kw-ci\">grossesse</span> à<span class=\"kw-chiffre\"> 6 mois</span> selon l'âge maternel : pic avant <span class=\"kw-chiffre\">25-28 ans</span>, déclin dès <span class=\"kw-chiffre\">31 ans</span>, <strong><span class=\"kw-chiffre\">35 ans</span> = seuil opérationnel</strong> (raccourcir le délai avant bilan), quasi nulle après <span class=\"kw-chiffre\">45 ans</span>.</figcaption>\n      </figure>\n\n      <table >\n        <thead>\n          <tr><th>Âge maternel</th><th>Probabilité de grossesse à <span class=\"kw-chiffre\">6 mois</span></th><th>Commentaire</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 25-28 ans</span></strong></td>\n            <td><span class=\"kw-chiffre\">60 %</span></td>\n            <td>Pic de fertilité ; recul de l’âge à la 1ʳᵉ <span class=\"kw-ci\">grossesse</span> = enjeu démographique</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">31 ans</span></strong></td>\n            <td>—</td>\n            <td><span class=\"kw-clinique\">Début du déclin</span> (mesurable mais lent)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">35 ans</span></strong></td>\n            <td><span class=\"kw-chiffre\">30 %</span></td>\n            <td>Chute marquée — seuil opérationnel pour <strong>raccourcir le délai avant bilan</strong></td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 45 ans</span></strong></td>\n            <td><span class=\"kw-chiffre\">≈ 0 %</span></td>\n            <td>Fertilité <span class=\"kw-alerte\">presque nulle</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs pronostiques principaux (femme)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Facteur</th><th>Effet</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>Réserve ovarienne décroît qualitativement et quantitativement</td>\n          </tr>\n          <tr>\n            <td><strong>Poids</strong></td>\n            <td>\n              <strong>IMC &gt;<span class=\"kw-chiffre\"> 30 kg/m²</span> :</strong> chances de <span class=\"kw-ci\">grossesse</span> divisées par <span class=\"kw-chiffre\">4</span> ; <br>\n              <strong>IMC trop bas :</strong> troubles de l’ovulation (anovulation hypothalamique)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Tabac</span></strong></td>\n            <td>\n              Diminution dose-dépendante : <span class=\"kw-clinique\">↑ délai de conception</span> ; <br>\n              ↑ risque de <span class=\"kw-alerte\">fausses couches, GEU, RCIU, mort fœtale in utero</span> ; <br>\n              ↑ risque de <span class=\"kw-alerte\">placenta praevia, HRP, RPM</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Fertilité masculine</h4>\n\n      <p>L’âge paternel est <span class=\"kw-clinique\">également associé à une diminution de la fertilité spontanée</span>, mais <strong>sans seuil précis</strong> (contrairement à la femme). Relation dose-effet entre <strong>IMC élevé</strong> et hypofertilité d’origine masculine.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 39 — Assistance médicale à la procréation · 124 — Ménopause - andropause</em></p>","frequence":1},{"id":"38-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire et de l’examen clinique chez la femme","contenu":"<p>Le bilan d’infertilité chez la femme est <strong>systématique et structuré</strong> en 4 axes : <span class=\"kw-clinique\">interrogatoire / terrain</span>, <span class=\"kw-clinique\">symptômes ciblés</span>, <span class=\"kw-clinique\">examen clinique</span>, <span class=\"kw-clinique\">dépistage</span>.</p>\n\n      <h4>Interrogatoire — <span class=\"kw-def\">Terrain</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Domaine</th><th>Items à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ATCD gynéco-obstétricaux</strong></td>\n            <td>\n              <strong>Gestité, parité :</strong> grossesses antérieures, IVG anciennes (++) ; <br>\n              <strong>IST, salpingite :</strong> Chlamydia ++ ; <br>\n              <strong><span class=\"kw-ttt\">Chirurgie</span> pelvienne :</strong> appendicite compliquée, myomectomie (risque d’adhérences) ; <br>\n              <strong>Chirurgie ovarienne :</strong> risque d’<span class=\"kw-alerte\">insuffisance ovarienne</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD médicaux</strong></td>\n            <td><span class=\"kw-clinique\">Diabète, épilepsie, maladies auto-immunes</span> — pouvant retentir sur une future <span class=\"kw-ci\">grossesse</span> ou nécessiter une programmation</td>\n          </tr>\n          <tr>\n            <td><strong>ATCD familiaux</strong></td>\n            <td>Pathologies génétiques, thrombophilies / ATCD thromboemboliques, ménopause précoce, cancer du sein, <span class=\"kw-def\">diabète</span>…</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Symptômes ciblés (recherche orientée)</h4>\n\n      <ul>\n        <li><strong>Durée et régularité des cycles</strong> → recherche d’un trouble de l’<span class=\"kw-clinique\">ovulation</span></li>\n        <li><span class=\"kw-clinique\">Dysménorrhée</span>, <span class=\"kw-clinique\">dyspareunie profonde</span> → évoque une <strong>endométriose</strong></li>\n        <li><span class=\"kw-alerte\">Bouffées de chaleur</span> → en faveur d’une <strong>insuffisance ovarienne prématurée (IOP)</strong></li>\n      </ul>\n\n      <h4>Examen clinique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Composante</th><th>Recherche</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Général</strong></td>\n            <td>Morphotype, <span class=\"kw-chiffre\">IMC</span>, signes d’<span class=\"kw-clinique\">hyperandrogénie</span> (hirsutisme, acné), <span class=\"kw-clinique\">acanthosis nigricans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Seins</strong></td>\n            <td>Recherche d’une <span class=\"kw-clinique\">galactorrhée</span> s’il existe des troubles du cycle (<strong>hyperprolactinémie</strong>)</td>\n          </tr>\n          <tr>\n            <td><strong>Gynécologique</strong></td>\n            <td>\n              Malformation génitale ; <br>\n              Signes indirects d’endométriose (<span class=\"kw-clinique\">utérus rétroversé, douleurs au TV</span>) ; <br>\n              Trophicité vaginale, état du col, présence de <span class=\"kw-clinique\">gros fibromyomes utérins</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Dépistage</span></h4>\n\n      <div class=\"callout callout-info\">\n        <strong>FCV de <span class=\"kw-def\">dépistage</span></strong> si le dernier date de <span class=\"kw-chiffre\">&gt; 3 ans</span>. Précède l’hystéro-salpingographie (interprétation difficile si pathologie cervicale méconnue).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 41 — Endométrisose · 162 — IST · 244 — Adénome hypophysaire</em></p>","frequence":0},{"id":"38-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire et de l’examen clinique chez l’homme","contenu":"<p>Bilan clinique masculin = <strong>4 axes</strong> : <span class=\"kw-def\">terrain</span> (toxiques, ATCD), symptômes (sexualité), examen (verge / volume testiculaire / varicocèle), distracteurs annales.</p>\n\n      <h4>Interrogatoire — <span class=\"kw-def\">Terrain</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Domaine</th><th>Items à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Profession</strong></td>\n            <td>Exposition aux <span class=\"kw-clinique\">toxiques</span> : chaleur, <strong>pesticides</strong>, <strong>polluants organochlorés</strong>, hydrocarbures, solvants, perturbateurs endocriniens</td>\n          </tr>\n          <tr>\n            <td><strong>Toxiques personnels</strong></td>\n            <td><span class=\"kw-clinique\">Tabac, cannabis</span> ; quantification de l’<span class=\"kw-etio\">alcool</span> ; <span class=\"kw-alerte\">dopage à la testostérone et/ou anabolisants (+++)</span></td>\n          </tr>\n          <tr>\n            <td><strong>ATCD génitaux</strong></td>\n            <td>\n              <strong>Ectopie testiculaire / cryptorchidie (+++)</strong> ; <br>\n              Torsion ou traumatisme testiculaire ; <br>\n              Infections (<span class=\"kw-clinique\">IST, oreillons</span>) ; <br>\n              ATCD d’<span class=\"kw-clinique\">hernie inguinale bilatérale opérée</span> (<span class=\"kw-clinique\">lésion</span> des déférents et/ou vascularisation testiculaire) ; <br>\n              Orchidopexie pour torsion du cordon spermatique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD médicaux</strong></td>\n            <td><span class=\"kw-clinique\">Mucoviscidose</span> (sinusites et bronchites à répétition)</td>\n          </tr>\n          <tr>\n            <td><strong>Traitements</strong></td>\n            <td><span class=\"kw-ttt\">Chimiothérapie</span>, radiothérapie, <strong>psychotropes</strong>, <strong>anticonvulsivants</strong>, <strong>stéroïdes</strong>, <strong>α-bloquants</strong>, <strong>inhibiteurs de la 5α-réductase</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Symptômes ciblés</h4>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Dysfonction sexuelle</span> : troubles de la libido, de l’érection, de l’éjaculation</li>\n        <li>Douleurs uro-génitales → infection (épididymite, <span class=\"kw-def\">prostatite</span>) ou <strong>varicocèle</strong></li>\n        <li>Signes digestifs ou respiratoires → <span class=\"kw-clinique\">mucoviscidose</span> (à explorer si évocateur)</li>\n      </ul>\n\n      <h4>Examen clinique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Composante</th><th>Recherche</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Morphotype</strong></td>\n            <td>Aspect <span class=\"kw-clinique\">gynoïde, eunuchoïde</span>, taille/poids, évaluation de la pilosité, gynécomastie bilatérale</td>\n          </tr>\n          <tr>\n            <td><strong>Signes d’hypoandrisme</strong></td>\n            <td>Faible pilosité, faible <span class=\"kw-clinique\">masse</span> musculaire, adiposité augmentée</td>\n          </tr>\n          <tr>\n            <td><strong>Verge et appareil externe</strong></td>\n            <td>Hypospadias, infection du méat, présence des épididymes, des canaux déférents, cicatrices chirurgicales</td>\n          </tr>\n          <tr>\n            <td><strong>Varicocèle</strong></td>\n            <td>Recherché en position debout + <span class=\"kw-clinique\">manœuvre de Valsalva</span>. <strong>Grader chaque côté</strong> (<span class=\"kw-chiffre\">1, 2 ou 3</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Volume testiculaire</strong></td>\n            <td>Mesuré à l’<span class=\"kw-clinique\">orchidomètre de Prader</span>. Volume normal = <span class=\"kw-chiffre\">15-20 mL</span>. ≈<span class=\"kw-chiffre\">80 %</span> du volume est constitué par les <strong>tubes séminifères</strong></td>\n          </tr>\n          <tr>\n            <td><strong>TR</strong></td>\n            <td>Non systématique. Recommandé si : ATCD <span class=\"kw-etio\">infectieux</span>, hypospermie, anomalie du plasma séminal, suspicion de déficit androgénique, ou âge justifiant la recherche d’un cancer de la prostate</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Distracteurs annales (à ne pas rechercher dans ce contexte).</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Signe de Prehn</span> → évoque une <strong>orchi-épididymite</strong>, pas une infertilité</li>\n          <li>Gynécomastie <strong>unilatérale</strong> n’oriente pas vers une infertilité (origine endocrinienne ⇒ généralement bilatérale)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 45 — Maladies génétiques · 162 — IST · 244 — Adénome hypophysaire</em></p>","frequence":1,"liens":[{"href":"https://fr.wikipedia.org/wiki/Orchidom%C3%A8tre","label":"Wikipedia — Orchidomètre (volume testiculaire)"}]},{"id":"38-6","rang":"B","rubrique":"Étiologies","titre":"Connaître l’orientation diagnostique en fonction du contexte et des manifestations associées","contenu":"<p>L’orientation étiologique se construit en croisant <strong>répartition des causes</strong>, <strong>facteurs pronostiques majeurs</strong> et <strong>signes d’appel</strong> orientant vers un mécanisme dominant (ovulatoire / tubaire / utérin / cervical / endométriose / masculin).</p>\n\n      <h4>Répartition des étiologies d’infertilité féminine (à connaître)</h4>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 196\" role=\"img\" aria-label=\"Répartition des étiologies d'infertilité féminine par fréquence : anovulations et dysovulations 40 %, étiologies tubo-péritonéales 30 %, endométriose 15 %, étiologies cervicales 4 %, étiologies utérines 4 %, sexologiques 2 %, autres 5 %.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"15\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Étiologies d'infertilité féminine — fréquence</text>\n          <rect class=\"fb-blue\" x=\"180\" y=\"30\" width=\"300\" height=\"15\" rx=\"3\"/>\n          <text class=\"tx-muted\" x=\"8\" y=\"41.5\" font-size=\"8.5\">Anovulation / dysovul.</text>\n          <text class=\"tx-blue\" x=\"486\" y=\"41.5\" font-size=\"9\" font-weight=\"700\"><span class=\"kw-chiffre\">40 %</span></text>\n          <rect class=\"fb-blue\" x=\"180\" y=\"54\" width=\"225\" height=\"15\" rx=\"3\"/>\n          <text class=\"tx-muted\" x=\"8\" y=\"65.5\" font-size=\"8.5\">Tubo-péritonéales</text>\n          <text class=\"tx-blue\" x=\"411\" y=\"65.5\" font-size=\"9\" font-weight=\"700\"><span class=\"kw-chiffre\">30 %</span></text>\n          <rect class=\"fb-blue\" x=\"180\" y=\"78\" width=\"112\" height=\"15\" rx=\"3\"/>\n          <text class=\"tx-muted\" x=\"8\" y=\"89.5\" font-size=\"8.5\">Endométriose</text>\n          <text class=\"tx-blue\" x=\"298\" y=\"89.5\" font-size=\"9\" font-weight=\"700\"><span class=\"kw-chiffre\">15 %</span></text>\n          <rect class=\"fb-grey\" x=\"180\" y=\"102\" width=\"30\" height=\"15\" rx=\"3\"/>\n          <text class=\"tx-muted\" x=\"8\" y=\"113.5\" font-size=\"8.5\">Cervicales</text>\n          <text class=\"tx-grey\" x=\"216\" y=\"113.5\" font-size=\"9\" font-weight=\"700\"><span class=\"kw-chiffre\">4 %</span></text>\n          <rect class=\"fb-grey\" x=\"180\" y=\"126\" width=\"30\" height=\"15\" rx=\"3\"/>\n          <text class=\"tx-muted\" x=\"8\" y=\"137.5\" font-size=\"8.5\">Utérines</text>\n          <text class=\"tx-grey\" x=\"216\" y=\"137.5\" font-size=\"9\" font-weight=\"700\"><span class=\"kw-chiffre\">4 %</span></text>\n          <rect class=\"fb-grey\" x=\"180\" y=\"150\" width=\"15\" height=\"15\" rx=\"3\"/>\n          <text class=\"tx-muted\" x=\"8\" y=\"161.5\" font-size=\"8.5\">Sexologiques</text>\n          <text class=\"tx-grey\" x=\"201\" y=\"161.5\" font-size=\"9\" font-weight=\"700\"><span class=\"kw-chiffre\">2 %</span></text>\n          <rect class=\"fb-grey\" x=\"180\" y=\"174\" width=\"38\" height=\"15\" rx=\"3\"/>\n          <text class=\"tx-muted\" x=\"8\" y=\"185.5\" font-size=\"8.5\">Autres</text>\n          <text class=\"tx-grey\" x=\"224\" y=\"185.5\" font-size=\"9\" font-weight=\"700\"><span class=\"kw-chiffre\">5 %</span></text>\n        </svg>\n        <figcaption>Trois causes dominent (anovulation <span class=\"kw-chiffre\">40 %</span> &gt; tubo-péritonéal <span class=\"kw-chiffre\">30 %</span> &gt; endométriose <span class=\"kw-chiffre\">15 %</span>) — total <span class=\"kw-chiffre\">100 %</span>. Ordre de fréquence à connaître.</figcaption>\n      </figure>\n\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Anovulations / dysovulations</strong></td><td><span class=\"kw-chiffre\">40 %</span></td></tr>\n          <tr><td><strong>Étiologies tubo-péritonéales</strong></td><td><span class=\"kw-chiffre\">30 %</span></td></tr>\n          <tr><td><strong>Endométriose</strong></td><td><span class=\"kw-chiffre\">15 %</span></td></tr>\n          <tr><td>Étiologies cervicales</td><td><span class=\"kw-chiffre\">4 %</span></td></tr>\n          <tr><td>Étiologies utérines</td><td><span class=\"kw-chiffre\">4 %</span></td></tr>\n          <tr><td>Sexologiques (dysfonctions du couple)</td><td><span class=\"kw-chiffre\">2 %</span></td></tr>\n          <tr><td>Autres</td><td><span class=\"kw-chiffre\">5 %</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Signes d’appel → orientation</h4>\n\n      <table >\n        <thead>\n          <tr><th>Signe d’appel</th><th>Mécanisme évoqué</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Aménorrhée ou cycles irréguliers</span></td>\n            <td><span class=\"kw-etio\">Anovulation</span> (<span class=\"kw-chiffre\">20 %</span> des infécondités) — explorer <span class=\"kw-etio\">SOPK</span>, <span class=\"kw-etio\">hyperprolactinémie</span>, <span class=\"kw-etio\">IOP</span>, déficit gonadotrope</td>\n          </tr>\n          <tr>\n            <td>Cycles réguliers (28 ± j)</td>\n            <td>N’élimine pas une anovulation — <span class=\"kw-clinique\">progestéronémie J22-23</span> obligatoire</td>\n          </tr>\n          <tr>\n            <td>Hirsutisme, acné, acanthosis nigricans</td>\n            <td><span class=\"kw-etio\">SOPK</span> ; doser <span class=\"kw-bio\">17OH-progestérone</span>, <span class=\"kw-bio\">testostérone totale</span>, Δ<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> an</span>drostènedione, SDHEA</td>\n          </tr>\n          <tr>\n            <td>Galactorrhée, troubles du cycle</td>\n            <td><span class=\"kw-etio\">Hyperprolactinémie</span> (<span class=\"kw-etio\">adénome hypophysaire</span>) — <span class=\"kw-bio\">prolactine</span> + <span class=\"kw-bio\">TSH</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Bouffées de chaleur</span></td>\n            <td><span class=\"kw-etio\">Insuffisance ovarienne prématurée (IOP)</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Dysménorrhée, dyspareunie profonde</span>, utérus rétroversé</td>\n            <td><span class=\"kw-etio\">Endométriose</span> (<span class=\"kw-chiffre\">4 %</span> population, <span class=\"kw-chiffre\">30-50 %</span> des femmes infertiles)</td>\n          </tr>\n          <tr>\n            <td>ATCD de <span class=\"kw-etio\">salpingite</span>, <span class=\"kw-etio\">Chlamydia</span>, <span class=\"kw-ttt\">chirurgie</span> pelvienne</td>\n            <td><span class=\"kw-etio\">Cause tubaire</span> (cause majeure d’infertilité féminine)</td>\n          </tr>\n          <tr>\n            <td>ATCD de conisation / <span class=\"kw-ttt\">curetage</span> / diathermo</td>\n            <td>Pathologie cervicale (sténose, glaire) → indication d’<span class=\"kw-ttt\">IAC</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège diagnostique.</strong> Des cycles cliniquement réguliers <strong>n’éliminent pas</strong> une anovulation — la <span class=\"kw-clinique\">progestéronémie au 22-23ᵉ jour</span> reste obligatoire dès qu’il existe une suspicion clinique.\n      </div>\n\n      <h4>Facteurs pronostiques majeurs (femme et homme)</h4>\n\n      <ul>\n        <li><strong>Âge</strong> — facteur N°1 chez la femme (effondrement de la réserve folliculaire après <span class=\"kw-chiffre\">35 ans</span>)</li>\n        <li><strong>Poids</strong> — IMC &gt; 30 = ÷4 chances de <span class=\"kw-ci\">grossesse</span> ; IMC trop bas = troubles de l’ovulation</li>\n        <li><strong><span class=\"kw-etio\">Tabac</span></strong> — dose-dépendant, ↑ délai de conception, fausses couches, GEU, RCIU, MFIU</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 41 — Endométrisose · 244 — Adénome hypophysaire · 124 — Ménopause - andropause</em></p>","frequence":2},{"id":"38-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan de première intention d’une infertilité féminine et/ou masculine","contenu":"<p>Le bilan de 1ʳᵉ intention est <strong>systématique et bilatéral</strong> (couple). Le Collège de Gynécologie ne mentionne que le <strong>spermogramme en <span class=\"kw-chiffre\">1ère intention</span> chez l’homme</strong>, le Collège d’Urologie est plus exhaustif et ajoute FSH/LH/Testostérone/<span class=\"kw-imagerie\">échographie</span> testiculaire d’emblée.</p>\n\n      <h4>Bilan femme — 4 axes</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe exploré</th><th>Examens 1ʳᵉ intention</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Ovulation</strong></td>\n            <td>\n              <span class=\"kw-bio\">Progestéronémie</span> au <span class=\"kw-chiffre\">22-23ᵉ jour</span> du cycle (indication si cycles <span class=\"kw-chiffre\">26-34 jours</span>) ; <br>\n              Si dysovulation : <span class=\"kw-bio\">prolactine + TSH</span> ; <br>\n              Si dysovulation + hyperandrogénie : <span class=\"kw-bio\">17OH-progestérone, testostérone totale, Δ4 androstènedione, SDHEA</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Réserve folliculaire</strong></td>\n            <td>\n              <span class=\"kw-bio\">FSH, LH, œstradiol</span> à <span class=\"kw-chiffre\">J3</span> — mauvais <span class=\"kw-def\">pronostic</span> si FSH ↑ <span class=\"kw-chiffre\">&gt; 12-15 UI/L</span> et œstradiol <span class=\"kw-chiffre\">&gt; 50 pg/mL</span> ; <br>\n              <span class=\"kw-imagerie\">Échographie pelvienne</span> sus-pubienne et endovaginale à <span class=\"kw-chiffre\">J3</span> — CFA péjoratif si <span class=\"kw-chiffre\">&lt; 5</span> ou <span class=\"kw-chiffre\">&gt; 10-20</span> ; <br>\n              <span class=\"kw-bio\">AMH</span> en 2ⁿᵈ intention (surtout si AMP prévue), <strong>à tout moment du cycle</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Appareil génital</strong></td>\n            <td>\n              <span class=\"kw-imagerie\">Hystérosalpingographie</span> (1ʳᵉ partie de cycle, vers J8-10, <strong>après avoir écarté une <span class=\"kw-ci\">grossesse</span></strong>) — <span class=\"kw-ci\">CI : allergie à l’iode, infection génitale</span> (<span class=\"kw-ttt\">antibioprophylaxie</span> si ATCD <span class=\"kw-etio\">infectieux</span> : risque d’endométrite / salpingite) ; <br>\n              <span class=\"kw-imagerie\">Échographie pelvienne</span> (2ⁿᵈ partie de cycle pour les processus endocavitaires) ; <br>\n              <span class=\"kw-imagerie\">Hystéro-sonographie</span> (alternative — perméabilité tubaire + processus endocavitaire) ; <br>\n              En 2ⁿᵈ intention : hystéroscopie, cœlioscopie diagnostique\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Sérologies</span> pré-<span class=\"kw-ci\">grossesse</span> / pré-AMP</strong></td>\n            <td><span class=\"kw-bio\">VIH, syphilis, VHB, VHC, rubéole, toxoplasmose, varicelle</span> (si absence d’ATCD clinique)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan homme — 1ʳᵉ intention</h4>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indication / valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Spermogramme + Spermocytogramme</strong></td>\n            <td><span class=\"kw-clinique\">SYSTÉMATIQUE</span> en 1ʳᵉ intention. Abstinence <span class=\"kw-chiffre\">3-5 jours</span> (uro : <span class=\"kw-chiffre\">2-7 j</span>), recueil par masturbation <strong>au laboratoire</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Spermoculture</strong></td>\n            <td>Si <span class=\"kw-clinique\">ATCD infectieux génito-urinaire</span> ou signes d’infection au spermogramme</td>\n          </tr>\n          <tr>\n            <td>Test de migration survie</td>\n            <td>En 2ⁿᵈ intention si <span class=\"kw-clinique\">OAT</span> (oligo-asthéno-tératospermie). Permet d’envisager le type d’AMP</td>\n          </tr>\n          <tr>\n            <td><strong>Confirmation d’anomalie</strong></td>\n            <td>Affirmée seulement après <span class=\"kw-chiffre\">≥ 2 spermogrammes à 3 mois d’intervalle</span> (spermatogenèse = <span class=\"kw-chiffre\">74 jours</span> ; variabilité intra-individuelle stress / <span class=\"kw-clinique\">fièvre</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Distracteurs d’annales — examens à NE PAS faire en <span class=\"kw-chiffre\">1ère intention</span>.</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Test post-coïtal (Huhner)</span> — explore l’interaction glaire cervicale / spermatozoïdes (<span class=\"kw-def\">score</span> d’<strong>Insler <span class=\"kw-chiffre\">≥ 8</span>/12</strong>). <strong>Non systématique</strong>, peu d’intérêt diagnostique ; réservé à étayer une infertilité inexpliquée.</li>\n          <li><span class=\"kw-clinique\">Courbe de température</span> (monothermique) — <strong>n’est plus recommandée</strong> ; remplacée par la progestéronémie J22-23.</li>\n        </ul>\n      </div>\n\n      <h4>Schémas de synthèse — bilan para-clinique <span class=\"kw-chiffre\">1ère intention</span></h4>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/38/bilan-1ere-intention-fig1.png\" alt=\"Schéma de synthèse du bilan paraclinique de 1ère intention dans l'infertilité du couple (femme et homme), tiré de la fiche source EDN item 38\" loading=\"lazy\">\n        <figcaption>Vue 1 — synthèse du bilan paraclinique de 1ʳᵉ intention (couple). Source : fiche source EDN item 38.</figcaption>\n      </figure>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/38/bilan-1ere-intention-fig2.png\" alt=\"Algorithme complémentaire — bilan paraclinique de 1ère intention dans l'infertilité du couple\" loading=\"lazy\">\n        <figcaption>Vue 2 — algorithme complémentaire du bilan paraclinique 1ʳᵉ intention. Source : fiche source EDN item 38.</figcaption>\n      </figure>\n\n      <h4>Mesures préconceptionnelles associées</h4>\n\n      <ul>\n        <li><strong>Vaccinations :</strong> rubéole si <span class=\"kw-bio\">sérologie</span> négative (éviter <span class=\"kw-ci\">grossesse</span> <span class=\"kw-chiffre\">2 mois</span> après), varicelle si pas d’ATCD (2 doses, contraception <span class=\"kw-chiffre\">3 mois</span> après chaque dose ⚠️), coqueluche (couple), <span class=\"kw-etio\">grippe</span> (<span class=\"kw-def\">terrain</span> à risque ou grossesse en cours)</li>\n        <li><strong>Alimentation :</strong> régime amaigrissant si IMC élevé, arrêt des toxiques (<span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">tabac</span>, cannabis, limitation caféine), <span class=\"kw-ttt\">acide folique 0,4 mg/j</span></li>\n        <li><strong>Risques spécifiques :</strong> équilibre préconceptionnel d’un <span class=\"kw-def\">diabète</span> (<span class=\"kw-chiffre\">HbA1c &lt; 6,5 %</span>), absence de traitement <span class=\"kw-ci\">tératogène</span>, <span class=\"kw-def\">dépistage</span> précarité / violence conjugale, évaluation pénibilité au travail</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 39 — Assistance médicale à la procréation · 35 — Anomalies cycle menstruel - métrorragie</em></p>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/hysterosalpingogram","label":"Radiopaedia : Hystérosalpingographie (HSG)"},{"href":"https://radiopaedia.org/articles/testicular-and-scrotal-ultrasound","label":"Radiopaedia : Échographie testiculaire & scrotale"},{"href":"https://radiopaedia.org/cases/scrotal-ultrasound-normal","label":"Radiopaedia : Échographie scrotale normale (cas)"}]},{"id":"38-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes d’interprétation d’un spermogramme","contenu":"<p>Le spermogramme normalisé (<strong>OMS</strong>) est l’examen <strong>pivot</strong> du bilan masculin. À interpréter conjointement avec le <span class=\"kw-clinique\">spermocytogramme</span> (morphologie) et la <span class=\"kw-clinique\">spermoculture</span> (si suspicion d’infection).</p>\n\n      <h4>Normes OMS — paramètres clés</h4>\n\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Norme OMS</th><th>Anomalie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Couleur</strong></td>\n            <td>Opalescent</td>\n            <td><span class=\"kw-clinique\">Orangé</span> → suspicion d’infection (spermoculture indiquée)</td>\n          </tr>\n          <tr>\n            <td><strong>Viscosité</strong></td>\n            <td>Normale</td>\n            <td>Hyperviscosité → témoin d’une <strong>insuffisance prostatique</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Volume</strong></td>\n            <td><span class=\"kw-chiffre\">&gt; 1,4 mL</span></td>\n            <td><strong>Hypospermie</strong> (&lt; <span class=\"kw-chiffre\">1,4 mL</span>) ou <strong>aspermie</strong> (absence). Évoque vieillissement ou <span class=\"kw-alerte\">agénésie des déférents</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">pH</span></strong></td>\n            <td><span class=\"kw-chiffre\">7,2 – 8</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Numération</strong></td>\n            <td>&gt; <span class=\"kw-chiffre\">16 M/mL</span> et &gt; <span class=\"kw-chiffre\">39 M / éjaculat</span></td>\n            <td>\n              <strong>Oligospermie</strong> (&lt; 16 M/mL ou &lt; 39 M/éjaculat) ; <br>\n              <strong>Azoospermie</strong> = absence totale (frais + culot après centrifugation 3 <span class=\"kw-chiffre\">000 g</span> × <span class=\"kw-chiffre\">15 min</span>) → <span class=\"kw-imagerie\">écho testiculaire</span> ; <br>\n              <strong>Cryptospermie</strong> (absent à l’état frais, spz dans le culot)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mobilité</strong></td>\n            <td>Totale ≥ <span class=\"kw-chiffre\">42 %</span> ; progressive ≥ <span class=\"kw-chiffre\">30 %</span></td>\n            <td><strong>Asthénospermie</strong> (mobilité progressive &lt; <span class=\"kw-chiffre\">30 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Vitalité</strong></td>\n            <td>&gt; <span class=\"kw-chiffre\">54 %</span></td>\n            <td><strong>Nécrospermie</strong> (&gt; <span class=\"kw-chiffre\">46 %</span> de spz morts, soit &lt; <span class=\"kw-chiffre\">54 %</span> de vitalité)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Leucocytes</span></strong></td>\n            <td>&lt; <span class=\"kw-chiffre\">1 M/mL</span></td>\n            <td><strong>Leucospermie</strong> (GB &gt; 1 M/mL) → évoque une <span class=\"kw-clinique\">infection</span></td>\n          </tr>\n          <tr>\n            <td><strong>Agglutinats</strong></td>\n            <td>Absents</td>\n            <td>Présence → <span class=\"kw-clinique\">AC anti-spz</span></td>\n          </tr>\n          <tr>\n            <td><strong>Spermocytogramme (morphologie)</strong></td>\n            <td>\n              ≥ <span class=\"kw-chiffre\">4 %</span> formes typiques (<strong>Kruger</strong>) ; <br>\n              ≥ <span class=\"kw-chiffre\">23-30 %</span> formes typiques (<strong>David</strong>)\n            </td>\n            <td><strong>Tératospermie</strong> (&lt; <span class=\"kw-chiffre\">4 %</span> Kruger ou &lt; <span class=\"kw-chiffre\">23-30 %</span> David)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>OATS</strong> (oligo-asthéno-tératospermie) = association <strong>≥ <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> an</span>omalies</strong> sur <strong><span class=\"kw-chiffre\">≥ 2</span> spermogrammes à <span class=\"kw-chiffre\">3 mois</span> d’intervalle</strong>. C’est l’entité de loin la plus fréquente chez l’homme infécond.\n      </div>\n\n      <h4>Explorations à enchaîner après spermogramme anormal</h4>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Bilan hormonal</strong></td>\n            <td>\n              Minimal (<span class=\"kw-clinique\">systématique</span> si azoospermie sécrétoire ou oligospermie &lt; 10 M/mL) = <span class=\"kw-bio\">Testostérone totale, LH, FSH</span> ; <br>\n              <span class=\"kw-bio\">Prolactine</span> si troubles de la libido + dysfonction sexuelle, gynécomastie inexpliquée, ou insuffisance gonadotrope\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> scrotale</strong></td>\n            <td>ATCD de pathologie testiculaire, anomalie de l’examen clinique, anomalie au spermogramme</td>\n          </tr>\n          <tr>\n            <td><strong>Caryotype</strong></td>\n            <td>\n              Anomalies chez <span class=\"kw-chiffre\">7 %</span> des hommes infertiles (dont 2/3 de Klinefelter XXY). Indiqué si : <br>\n              · Infertilité inexpliquée ; <br>\n              · <strong>Azoospermie sécrétoire</strong> (<span class=\"kw-chiffre\">17 %</span> d’anomalies) ; <br>\n              · <strong>Oligospermie &lt; 10 M/mL</strong> (≈ <span class=\"kw-chiffre\">10 %</span> si &lt; 5 M ; ≈ <span class=\"kw-chiffre\">4 %</span> entre 5-10 M) ; <br>\n              · Histoire familiale d’avortement à répétition, malformations, retards mentaux\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Microdélétions du chromosome Y</strong></td>\n            <td>≈ <span class=\"kw-chiffre\">2 %</span> des hommes avec azoospermie. Indiqué si <span class=\"kw-clinique\">azoospermie sécrétoire</span> ou <span class=\"kw-clinique\">oligospermie sévère &lt; 1 M/mL</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mutations du gène CFTR</strong></td>\n            <td>\n              Indications : <span class=\"kw-alerte\">absence bilatérale des canaux déférents</span> et/ou symptômes de mucoviscidose ; <br>\n              <span class=\"kw-clinique\">Recherche obligatoire chez la partenaire</span> si mutation chez l’homme (conseil <span class=\"kw-etio\">génétique</span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 39 — Assistance médicale à la procréation · 162 — IST</em></p>","frequence":2},{"id":"38-9","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes d’infertilité chez la femme","contenu":"<p>Cinq grandes catégories étiologiques. À mémoriser dans <strong>l’ordre de fréquence</strong> (anovulation &gt; tubaire &gt; endométriose &gt; utérine ≈ cervicale).</p>\n\n      <h4>1. Anovulations / dysovulations <span class=\"kw-chiffre\">(40 %)</span></h4>\n\n      <ul>\n        <li><strong>Anovulation</strong> (<span class=\"kw-chiffre\">20 %</span> des infécondités) — aménorrhée ou irrégularités menstruelles (attention : cycles réguliers n’éliminent pas une anovulation)</li>\n        <li><strong>Dysovulations</strong> — <span class=\"kw-clinique\">phase lutéale courte ou défectueuse</span>, avec sécrétion insuffisante de progestérone</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Étiologies par ordre de fréquence décroissante :</strong> <br>\n        <span class=\"kw-etio\">SOPK</span> &gt; hyperprolactinémie &gt; baisse de la réserve ovarienne (voire <span class=\"kw-etio\">IOP</span>) &gt; déficit gonadotrope d’origine hypophysaire &gt; déficit gonadotrope d’origine hypothalamique (surtout psychonutritionnelle)\n      </div>\n\n      <h4>2. Étiologies tubo-péritonéales <span class=\"kw-chiffre\">(30 %)</span> — <strong>cause majeure</strong></h4>\n\n      <ul>\n        <li><strong>Obstacle tubaire :</strong> <span class=\"kw-etio\">salpingite</span> (Chlamydia ++, parfois passée inaperçue), traumatisme chirurgical, endométriose</li>\n        <li><strong>Examens diagnostiques :</strong>\n          <ul>\n            <li><span class=\"kw-imagerie\">Hystérosalpingographie</span> — montre l’obstacle, ou diverticules évocateurs d’endométriose</li>\n            <li><span class=\"kw-imagerie\">Cœlioscopie avec épreuve au bleu</span> — inventaire des lésions ± gestes thérapeutiques</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Obstacle tubaire bilatéral = indication majeure de FIV</strong> (fécondation in vitro).\n      </div>\n\n      <h4>3. Endométriose <span class=\"kw-chiffre\">(15 %)</span></h4>\n\n      <ul>\n        <li>Toucherait <span class=\"kw-chiffre\">4 %</span> des femmes, mais retrouvée chez <span class=\"kw-chiffre\">30-50 %</span> des femmes infertiles</li>\n        <li><span class=\"kw-imagerie\">Hystérographie</span> :\n          <ul>\n            <li>Diverticules du segment interstitiel des trompes — images en <span class=\"kw-clinique\">« boule de gui »</span></li>\n            <li>Images d’angulation ou de rétention ampullaire</li>\n          </ul>\n        </li>\n        <li><span class=\"kw-imagerie\">IRM pelvienne</span> — indiquée pour bilan des lésions (anomalie HSG / écho pelvienne)</li>\n        <li><span class=\"kw-imagerie\">Cœlioscopie</span> si HSG normale et signes d’appel — foyers d’endométriose (<span class=\"kw-clinique\">grains bleutés</span>)</li>\n      </ul>\n\n      <h4>4. Étiologies utérines <span class=\"kw-chiffre\">(4 %)</span></h4>\n\n      <ul>\n        <li><strong>Cloisonnement, synéchies</strong> (infectieuses ou post-manœuvres endo-utérines post-partum / post-IVG)</li>\n        <li><strong>Polypes muqueux, fibromes sous-muqueux, hyperplasie endométriale</strong></li>\n        <li><strong>Démarche diagnostique :</strong>\n          <ul>\n            <li>1ʳᵉ intention : <span class=\"kw-imagerie\">hystérosalpingographie</span>, <span class=\"kw-imagerie\">échographie avec produit de contraste</span></li>\n            <li>2ⁿᵈ intention : <span class=\"kw-imagerie\">hystéroscopie</span> (diagnostic + traitement possible : synéchie de petite taille)</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>5. Étiologies cervicales <span class=\"kw-chiffre\">(4 %)</span></h4>\n\n      <p>Sténoses cervicales (post-<strong>conisation</strong>, <strong><span class=\"kw-ttt\">curetage</span></strong> ou <strong>diathermocoagulation</strong> de l’endocol) → pathologie de la glaire cervicale → <span class=\"kw-ttt\">indication de choix aux inséminations intra-utérines avec sperme du conjoint (IAC)</span>.</p>\n\n      <h4>6. Sexologiques <span class=\"kw-chiffre\">(2 %)</span></h4>\n\n      <ul>\n        <li>Vaginisme, dyspareunie, dysfonction érectile chez le partenaire</li>\n        <li>Optimisation des chances : rapports <strong><span class=\"kw-chiffre\">1 jour</span> sur 2</strong>, fenêtre de fertilité = <span class=\"kw-chiffre\">5 jours précédant l’ovulation</span></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 41 — Endométrisose · 124 — Ménopause - andropause · 244 — Adénome hypophysaire</em></p>","frequence":0},{"id":"38-10","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes d’infertilité chez l’homme","contenu":"<p>Trois grandes catégories étiologiques chez l’homme, qu’il faut savoir <strong>discriminer sur le couple <span class=\"kw-bio\">Volume testiculaire / FSH</span></strong> (synthèse stratégique).</p>\n\n      <h4>Synthèse — discrimination par volume testiculaire et FSH</h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Volume testiculaire</th><th>FSH</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Azoospermie sécrétoire</strong> (non-obstructive)</td>\n            <td>Normal ou <span class=\"kw-chiffre\">&lt; 10 mL</span> (presque toujours sécrétoire si vol &lt; <span class=\"kw-chiffre\">10 mL</span>)</td>\n            <td>\n              <strong>FSH élevée (le plus souvent)</strong> → atteinte testiculaire ; <br>\n              <strong>FSH basse/normale + testostérone basse</strong> → atteinte <span class=\"kw-clinique\">centrale</span> (signes d’hypogonadisme au 1er plan)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Azoospermie excrétoire</strong> (obstructive)</td>\n            <td>Normal (spermatogénèse normale)</td>\n            <td>Normale</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>1. Azoospermie sécrétoire (non-obstructive)</h4>\n\n      <p><strong>Mécanisme :</strong> défaut de spermatogenèse (absence de production par les testicules).</p>\n\n      <table >\n        <thead>\n          <tr><th>FSH</th><th>Mécanisme + bilan</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>FSH élevée</strong> (origine testiculaire — <span class=\"kw-chiffre\">60 %</span> des azoospermies sécrétoires)</td>\n            <td>\n              ATCD : <span class=\"kw-clinique\">cryptorchidie ++</span>, séquelles d’oreillons… ; <br>\n              <span class=\"kw-imagerie\">Échographie testiculaire</span> : éliminer cancer testiculaire ou varicocèle ; <br>\n              <strong>Caryotype</strong> (systématique 1ʳᵉ intention) : <span class=\"kw-alerte\">syndrome de Klinefelter</span> (volume testiculaire &lt; <span class=\"kw-chiffre\">1-2 mL</span>) ; <br>\n              <strong>Recherche microdélétions du chromosome Y</strong> : doit être réalisée\n            </td>\n          </tr>\n          <tr>\n            <td><strong>FSH normale ou basse</strong> + testostérone basse + LH normales/basses (atteinte centrale, plus rare)</td>\n            <td>\n              Hypogonadisme hypothalamique ou hypophysaire ; <br>\n              <strong>Clinique :</strong> signes d’hypogonadisme au 1er plan (retard de puberté, dysfonction sexuelle, infertilité) ; <br>\n              <strong>Étiologies :</strong> <span class=\"kw-clinique\">Syndrome de Kallmann-de-Morsier</span>, <span class=\"kw-clinique\">tumeurs hypophysaires</span> ; <br>\n              <strong>PEC :</strong> curable par <span class=\"kw-ttt\">gonadotrophines exogènes</span> (simple)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2. Azoospermie excrétoire (obstructive)</h4>\n\n      <p><strong>Mécanisme :</strong> obstacle bilatéral sur les voies excrétrices (<span class=\"kw-clinique\">épididyme, canaux déférents, canaux éjaculateurs</span>) — spermatogénèse normale.</p>\n\n      <table >\n        <thead>\n          <tr><th>Démarche</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>Dilatation épididymaire bilatérale ; anomalies (absence, <span class=\"kw-clinique\">nodule</span>, dilatation) des voies séminales</td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td><span class=\"kw-imagerie\">Échographie scrotale</span> + organes génitaux internes (précise le site de l’obstruction)</td>\n          </tr>\n          <tr>\n            <td><strong>Causes acquises</strong></td>\n            <td>\n              <strong>Infectieuses +++</strong> (gonocoque, Chlamydia présumés) ; <br>\n              Chirurgicales, traumatiques (ex. hernie inguine/scrotale, rare) ; <br>\n              Déférent souvent palpable, parfois gros / nodulaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Causes congénitales</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Agénésies bilatérales des canaux déférents (+++)</span> = anomalie biallélique du gène <strong>CFTR</strong> (Cystic Fibrosis Transmembrane Regulator, ABCC7), aussi responsable de la <span class=\"kw-clinique\">mucoviscidose</span> : <br>\n              · Non-perception des déférents à la palpation + distension de la tête épididymaire + atrophie du corps ; <br>\n              · Si forme sévère : anomalies pancréas exocrine + infections bronchopulmonaires sévères + agénésie bilatérale = mucoviscidose typique ; <br>\n              · Si forme génitale isolée : <span class=\"kw-bio\">analyse moléculaire CFTR</span> pour confirmer + conseil <span class=\"kw-etio\">génétique</span> + <strong>exploration de la conjointe</strong> (fréquence élevée de mutations hétérozygotes en population générale)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3. Oligo-asthéno-térato-spermie (OATS) — la plus fréquente</h4>\n\n      <p>Groupe <strong>hétérogène</strong>, de loin le plus fréquent chez l’homme infécond. Associe sur <span class=\"kw-chiffre\">≥ 2</span> spermogrammes : anomalies quantitatives <strong>et/ou</strong> qualitatives (mobilité, vitalité, % formes normales).</p>\n\n      <table >\n        <thead>\n          <tr><th>Domaine</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ATCD</strong></td>\n            <td><span class=\"kw-clinique\">Varicocèle</span>, infectieuses, <span class=\"kw-clinique\">cryptorchidie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Génétiques</strong></td>\n            <td>Anomalies du caryotype, <span class=\"kw-alerte\">microdélétion Y AZFc</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mode de vie</strong></td>\n            <td><strong><span class=\"kw-etio\">Tabac</span>, cannabis, <span class=\"kw-etio\">alcool</span></strong>, <span class=\"kw-clinique\">hamams trop fréquents</span> (chaleur ++)</td>\n          </tr>\n          <tr>\n            <td><strong>Profession</strong></td>\n            <td>Pesticides, hydrocarbures, solvants, perturbateurs endocriniens</td>\n          </tr>\n          <tr>\n            <td><strong>Idiopathique</strong></td>\n            <td>≈ <span class=\"kw-chiffre\">40 %</span> des cas — aucune cause retrouvée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Enquête étiologique en cas d’OAT extrême</strong> (&lt; <span class=\"kw-chiffre\">5 × 10⁶ spz/mL</span>, chez <span class=\"kw-chiffre\">10 %</span> des patients) : <br>\n        1. <strong>Caryotype</strong> systématique ; <br>\n        2. <strong>Microdélétions du bras long du chromosome Y</strong> si caryotype normal.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Distracteurs annales.</strong> <span class=\"kw-clinique\">Prostatite chronique</span> et <span class=\"kw-clinique\">épididymite</span> n’ont <strong>pas de lien prouvé</strong> avec les OATS — contrairement à l’<span class=\"kw-alerte\">orchite</span> (post-oreillons ++).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 45 — Maladies génétiques · 162 — IST · 244 — Adénome hypophysaire</em></p>","frequence":3}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/hysterosalpingogram","label":"radiopaedia.org"},{"href":"https://fr.wikipedia.org/wiki/Orchidom%C3%A8tre","label":"fr.wikipedia.org"},{"href":"https://radiopaedia.org/articles/testicular-and-scrotal-ultrasound","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/cases/scrotal-ultrasound-normal","label":"radiopaedia.org"}],"cards":[{"i":"48a0d893264c","n":38,"o":"38-1","u":"Définition","t":"Connaître la définition de la fertilité, fécondité, fécondabilité d’un couple","q":"Quelle est la définition de la fécondabilité d'un couple et son ordre de grandeur ?","a":"<p>La <strong>fécondabilité</strong> est la probabilité pour un couple de concevoir au cours d'un <strong>cycle menstruel</strong>. Chez un couple normal, elle est d'environ <strong>25 %</strong> par cycle.</p>"},{"i":"e6391ed62615","n":38,"o":"38-1","u":"Définition","t":"Connaître la définition de la fertilité, fécondité, fécondabilité d’un couple","q":"Quelle est la définition de la fertilité pour un couple et quels sont les ordres de grandeur à retenir en fonction de l'âge ?","a":"<p>La <strong>fertilité</strong> représente la capacité potentielle d'un couple à obtenir une grossesse.</p><ul><li>À <strong>25 ans</strong>, la fertilité est d'environ <strong>60 %</strong> de grossesses à 6 mois.</li><li>À <strong>35 ans</strong>, elle diminue à environ <strong>30 %</strong> de grossesses à 6 mois.</li><li>La fertilité est maximale avant <strong>25-28 ans</strong>, diminue dès <strong>31 ans</strong>, et chute après <strong>35 ans</strong>, devenant presque nulle après <strong>45 ans</strong>.</li></ul>"},{"i":"ec906d671cc7","n":38,"o":"38-1","u":"Définition","t":"Connaître la définition de la fertilité, fécondité, fécondabilité d’un couple","q":"Comment définit-on la fécondité d'un couple ?","a":"<p>La <strong>fécondité</strong> est le résultat effectif de la conception, c'est-à-dire le fait d'avoir eu une <strong>naissance vivante</strong>. C'est un indicateur démographique (taux de natalité).</p>"},{"i":"2b12f6298f92","n":38,"o":"38-2","u":"Définition","t":"Connaître la définition d’un couple infertile","q":"Quelle est la définition de l'infertilité du couple selon l'OMS ?","a":"<p>Selon l'OMS, un couple est considéré infertile en l'absence de grossesse après au moins <strong>12 mois</strong> de rapports sexuels réguliers non protégés, chez un couple en âge de procréer.</p>"},{"i":"3c3a6d811817","n":38,"o":"38-2","u":"Définition","t":"Connaître la définition d’un couple infertile","q":"Quel est l'objectif principal de la définition opérationnelle de l'infertilité en pratique clinique ?","a":"<p>L'objectif principal de la définition opérationnelle de l'infertilité est de servir de <strong>déclencheur au bilan d'infertilité du couple</strong>, incluant une consultation dédiée et des examens de première intention.</p>"},{"i":"44b3b7f2a732","n":38,"o":"38-2","u":"Définition","t":"Connaître la définition d’un couple infertile","q":"Quand faut-il initier de manière plus précoce le bilan d'infertilité d'un couple ?","a":"<p>Il faut initier de manière plus précoce le bilan d'infertilité en cas d'<strong>âge maternel supérieur ou égal à 35 ans</strong> ou d'<strong>antécédents faisant suspecter une cause d'infertilité</strong> (ex: chirurgie pelvienne, IST, aménorrhée).</p>"}]};